export type StringKey = keyof typeof STRINGS;

/** Localized string with {name} placeholders filled from params. */
export function tr(key: StringKey | string, lang: Lang, params?: Record<string, string | number>): string {
  const entry = (STRINGS as Record<string, LocalizedText>)[key];
  let text = entry ? entry[lang] || entry.en : key;
  if (params) text = text.replace(/\{(\w+)\}/g, (m, name: string) => (name in params ? String(params[name]) : m));
  return text;
}

/** Body class / subclass label, falling back to the raw value (spectral types such as 'G2V' are shown as is). */
export function classLabel(value: string, lang: Lang, kind: 'class' | 'subclass' = 'class'): string {
  const key = kind + '.' + value;
  return key in STRINGS ? tr(key, lang) : value;
}

